  glow.addColorStop(0.18, `rgba(255, 184, 76, ${Math.min(1, 0.62 * intensity)})`);
  glow.addColorStop(0.42, `rgba(255, 125, 38, ${Math.min(0.8, 0.30 * intensity)})`);
  glow.addColorStop(1, 'rgba(255, 103, 32, 0)');
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, size, size);

  const safeProgress = Math.max(0, Math.min(1, Number(progress) || 0));
  const litSegments = Math.min(16, Math.floor(safeProgress * 16));
  const hue = 210 - safeProgress * 172;
  const center = size / 2;
  const radius = size * 0.414;
